with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'إدارة الكوارث والاستجابة للطوارئ الجوية','حوكمة مخاطر الطقس والإنذار متعدد المخاطر ومراكز الطوارئ والتنسيق والاستجابة والتعافي والتقييم.',42,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'إدارة المخاطر والاستعداد',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الاستجابة والتعافي والتقييم',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('disaster-risk-governance-weather','حوكمة مخاطر الكوارث المرتبطة بالطقس','الأدوار المؤسسية والتنسيق وإدارة المخاطر.','{"blocks":[{"type":"text","text":"يقدم الدرس حوكمة مخاطر الكوارث المرتبطة بالطقس ضمن منظومة الحد من مخاطر الكوارث المرتبطة بالظواهر الجوية."},{"type":"text","text":"الهدف: الأدوار المؤسسية والتنسيق وإدارة المخاطر. مع توضيح المسؤوليات وحدود الصلاحيات وآليات التنسيق."},{"type":"text","text":"تبدأ المنظومة بتحديد المخاطر ذات الأولوية والجهات المسؤولة والموارد والبيانات اللازمة."},{"type":"text","text":"توضع إجراءات تشغيل معيارية تحدد من يجمع المعلومات ومن يحللها ومن يعتمد الرسالة ومن يتابع الاستجابة."},{"type":"text","text":"تدمج معلومات الرصد والتوقع والخرائط والتعرض والآثار في صورة تشغيلية مشتركة."},{"type":"text","text":"تحدد مستويات التحذير والعتبات ومواعيد التحديث وفق المعايير الوطنية والقطاعية المعتمدة."},{"type":"text","text":"تراعى مهلة وصول الرسالة وفهمها وقدرة الجهات والمجتمعات على اتخاذ الإجراء المناسب."},{"type":"text","text":"تختبر الإجراءات عبر تمارين دورية وسيناريوهات متعددة وتوثق فجوات الاتصال والموارد."},{"type":"text","text":"بعد الحدث تجمع البيانات وتراجع القرارات والتوقعات والتأثيرات بصورة منهجية."},{"type":"text","text":"تحول نتائج المراجعة إلى إجراءات تصحيحية محددة المسؤول والموعد ومؤشر الإنجاز."},{"type":"text","text":"مثال تطبيقي: تمرين مكتبي يحاكي تطور حالة جوية شديدة من الرصد الأولي إلى التحذير ثم الاستجابة والتقييم."},{"type":"callout","text":"الخلاصة: إدارة الكوارث الجوية سلسلة مؤسسية متكاملة لا تنجح بالتحذير وحده دون استعداد واتصال واستجابة وتعلم."}]}',4760,55,'["تحديد الأدوار والمسؤوليات","تطبيق إجراءات الاستعداد والاستجابة","تقييم الأداء وتحسين المنظومة"]','إدارة المخاطر والاستعداد'),
('national-multi-hazard-early-warning-framework','الإطار الوطني للإنذار المبكر متعدد المخاطر','عناصر الرصد والتحليل والتحذير والاستجابة.','{"blocks":[{"type":"text","text":"يقدم الدرس الإطار الوطني للإنذار المبكر متعدد المخاطر ضمن منظومة الحد من مخاطر الكوارث المرتبطة بالظواهر الجوية."},{"type":"text","text":"الهدف: عناصر الرصد والتحليل والتحذير والاستجابة. مع توضيح المسؤوليات وحدود الصلاحيات وآليات التنسيق."},{"type":"text","text":"تبدأ المنظومة بتحديد المخاطر ذات الأولوية والجهات المسؤولة والموارد والبيانات اللازمة."},{"type":"text","text":"توضع إجراءات تشغيل معيارية تحدد من يجمع المعلومات ومن يحللها ومن يعتمد الرسالة ومن يتابع الاستجابة."},{"type":"text","text":"تدمج معلومات الرصد والتوقع والخرائط والتعرض والآثار في صورة تشغيلية مشتركة."},{"type":"text","text":"تحدد مستويات التحذير والعتبات ومواعيد التحديث وفق المعايير الوطنية والقطاعية المعتمدة."},{"type":"text","text":"تراعى مهلة وصول الرسالة وفهمها وقدرة الجهات والمجتمعات على اتخاذ الإجراء المناسب."},{"type":"text","text":"تختبر الإجراءات عبر تمارين دورية وسيناريوهات متعددة وتوثق فجوات الاتصال والموارد."},{"type":"text","text":"بعد الحدث تجمع البيانات وتراجع القرارات والتوقعات والتأثيرات بصورة منهجية."},{"type":"text","text":"تحول نتائج المراجعة إلى إجراءات تصحيحية محددة المسؤول والموعد ومؤشر الإنجاز."},{"type":"text","text":"مثال تطبيقي: تمرين مكتبي يحاكي تطور حالة جوية شديدة من الرصد الأولي إلى التحذير ثم الاستجابة والتقييم."},{"type":"callout","text":"الخلاصة: إدارة الكوارث الجوية سلسلة مؤسسية متكاملة لا تنجح بالتحذير وحده دون استعداد واتصال واستجابة وتعلم."}]}',4770,55,'["تحديد الأدوار والمسؤوليات","تطبيق إجراءات الاستعداد والاستجابة","تقييم الأداء وتحسين المنظومة"]','إدارة المخاطر والاستعداد'),
