('incident-command-weather-support','دعم الأرصاد لنظام قيادة الحوادث','تقديم المعلومات للميدان وتحديث صورة الحالة.','{"blocks":[{"type":"text","text":"يقدم الدرس دعم الأرصاد لنظام قيادة الحوادث ضمن منظومة الحد من مخاطر الكوارث المرتبطة بالظواهر الجوية."},{"type":"text","text":"الهدف: تقديم المعلومات للميدان وتحديث صورة الحالة. مع توضيح المسؤوليات وحدود الصلاحيات وآليات التنسيق."},{"type":"text","text":"تبدأ المنظومة بتحديد المخاطر ذات الأولوية والجهات المسؤولة والموارد والبيانات اللازمة."},{"type":"text","text":"توضع إجراءات تشغيل معيارية تحدد من يجمع المعلومات ومن يحللها ومن يعتمد الرسالة ومن يتابع الاستجابة."},{"type":"text","text":"تدمج معلومات الرصد والتوقع والخرائط والتعرض والآثار في صورة تشغيلية مشتركة."},{"type":"text","text":"تحدد مستويات التحذير والعتبات ومواعيد التحديث وفق المعايير الوطنية والقطاعية المعتمدة."},{"type":"text","text":"تراعى مهلة وصول الرسالة وفهمها وقدرة الجهات والمجتمعات على اتخاذ الإجراء المناسب."},{"type":"text","text":"تختبر الإجراءات عبر تمارين دورية وسيناريوهات متعددة وتوثق فجوات الاتصال والموارد."},{"type":"text","text":"بعد الحدث تجمع البيانات وتراجع القرارات والتوقعات والتأثيرات بصورة منهجية."},{"type":"text","text":"تحول نتائج المراجعة إلى إجراءات تصحيحية محددة المسؤول والموعد ومؤشر الإنجاز."},{"type":"text","text":"مثال تطبيقي: تمرين مكتبي يحاكي تطور حالة جوية شديدة من الرصد الأولي إلى التحذير ثم الاستجابة والتقييم."},{"type":"callout","text":"الخلاصة: إدارة الكوارث الجوية سلسلة مؤسسية متكاملة لا تنجح بالتحذير وحده دون استعداد واتصال واستجابة وتعلم."}]}',4790,55,'["تحديد الأدوار والمسؤوليات","تطبيق إجراءات الاستعداد والاستجابة","تقييم الأداء وتحسين المنظومة"]','إدارة المخاطر والاستعداد'),
('weather-disaster-contingency-planning','خطط الطوارئ للظواهر الجوية الشديدة','سيناريوهات الاستعداد وتوزيع الموارد والمسؤوليات.','{"blocks":[{"type":"text","text":"يقدم الدرس خطط الطوارئ للظواهر الجوية الشديدة ضمن منظومة الحد من مخاطر الكوارث المرتبطة بالظواهر الجوية."},{"type":"text","text":"الهدف: سيناريوهات الاستعداد وتوزيع الموارد والمسؤوليات. مع توضيح المسؤوليات وحدود الصلاحيات وآليات التنسيق."},{"type":"text","text":"تبدأ المنظومة بتحديد المخاطر ذات الأولوية والجهات المسؤولة والموارد والبيانات اللازمة."},{"type":"text","text":"توضع إجراءات تشغيل معيارية تحدد من يجمع المعلومات ومن يحللها ومن يعتمد الرسالة ومن يتابع الاستجابة."},{"type":"text","text":"تدمج معلومات الرصد والتوقع والخرائط والتعرض والآثار في صورة تشغيلية مشتركة."},{"type":"text","text":"تحدد مستويات التحذير والعتبات ومواعيد التحديث وفق المعايير الوطنية والقطاعية المعتمدة."},{"type":"text","text":"تراعى مهلة وصول الرسالة وفهمها وقدرة الجهات والمجتمعات على اتخاذ الإجراء المناسب."},{"type":"text","text":"تختبر الإجراءات عبر تمارين دورية وسيناريوهات متعددة وتوثق فجوات الاتصال والموارد."},{"type":"text","text":"بعد الحدث تجمع البيانات وتراجع القرارات والتوقعات والتأثيرات بصورة منهجية."},{"type":"text","text":"تحول نتائج المراجعة إلى إجراءات تصحيحية محددة المسؤول والموعد ومؤشر الإنجاز."},{"type":"text","text":"مثال تطبيقي: تمرين مكتبي يحاكي تطور حالة جوية شديدة من الرصد الأولي إلى التحذير ثم الاستجابة والتقييم."},{"type":"callout","text":"الخلاصة: إدارة الكوارث الجوية سلسلة مؤسسية متكاملة لا تنجح بالتحذير وحده دون استعداد واتصال واستجابة وتعلم."}]}',4800,55,'["تحديد الأدوار والمسؤوليات","تطبيق إجراءات الاستعداد والاستجابة","تقييم الأداء وتحسين المنظومة"]','إدارة المخاطر والاستعداد'),
('critical-infrastructure-weather-risk','مخاطر الطقس على البنية التحتية الحيوية','تحديد الأصول الحساسة والاعتماد المتبادل.','{"blocks":[{"type":"text","text":"يقدم الدرس مخاطر الطقس على البنية التحتية الحيوية ضمن منظومة الحد من مخاطر الكوارث المرتبطة بالظواهر الجوية."},{"type":"text","text":"الهدف: تحديد الأصول الحساسة والاعتماد المتبادل. مع توضيح المسؤوليات وحدود الصلاحيات وآليات التنسيق."},{"type":"text","text":"تبدأ المنظومة بتحديد المخاطر ذات الأولوية والجهات المسؤولة والموارد والبيانات اللازمة."},{"type":"text","text":"توضع إجراءات تشغيل معيارية تحدد من يجمع المعلومات ومن يحللها ومن يعتمد الرسالة ومن يتابع الاستجابة."},{"type":"text","text":"تدمج معلومات الرصد والتوقع والخرائط والتعرض والآثار في صورة تشغيلية مشتركة."},{"type":"text","text":"تحدد مستويات التحذير والعتبات ومواعيد التحديث وفق المعايير الوطنية والقطاعية المعتمدة."},{"type":"text","text":"تراعى مهلة وصول الرسالة وفهمها وقدرة الجهات والمجتمعات على اتخاذ الإجراء المناسب."},{"type":"text","text":"تختبر الإجراءات عبر تمارين دورية وسيناريوهات متعددة وتوثق فجوات الاتصال والموارد."},{"type":"text","text":"بعد الحدث تجمع البيانات وتراجع القرارات والتوقعات والتأثيرات بصورة منهجية."},{"type":"text","text":"تحول نتائج المراجعة إلى إجراءات تصحيحية محددة المسؤول والموعد ومؤشر الإنجاز."},{"type":"text","text":"مثال تطبيقي: تمرين مكتبي يحاكي تطور حالة جوية شديدة من الرصد الأولي إلى التحذير ثم الاستجابة والتقييم."},{"type":"callout","text":"الخلاصة: إدارة الكوارث الجوية سلسلة مؤسسية متكاملة لا تنجح بالتحذير وحده دون استعداد واتصال واستجابة وتعلم."}]}',4810,55,'["تحديد الأدوار والمسؤوليات","تطبيق إجراءات الاستعداد والاستجابة","تقييم الأداء وتحسين المنظومة"]','إدارة المخاطر والاستعداد'),
