('national-weather-disaster-review','المراجعة الوطنية لمنظومة الكوارث الجوية','تقييم القدرات وخطة التحسين المؤسسي.','{"blocks":[{"type":"text","text":"يقدم الدرس المراجعة الوطنية لمنظومة الكوارث الجوية ضمن منظومة الحد من مخاطر الكوارث المرتبطة بالظواهر الجوية."},{"type":"text","text":"الهدف: تقييم القدرات وخطة التحسين المؤسسي. مع توضيح المسؤوليات وحدود الصلاحيات وآليات التنسيق."},{"type":"text","text":"تبدأ المنظومة بتحديد المخاطر ذات الأولوية والجهات المسؤولة والموارد والبيانات اللازمة."},{"type":"text","text":"توضع إجراءات تشغيل معيارية تحدد من يجمع المعلومات ومن يحللها ومن يعتمد الرسالة ومن يتابع الاستجابة."},{"type":"text","text":"تدمج معلومات الرصد والتوقع والخرائط والتعرض والآثار في صورة تشغيلية مشتركة."},{"type":"text","text":"تحدد مستويات التحذير والعتبات ومواعيد التحديث وفق المعايير الوطنية والقطاعية المعتمدة."},{"type":"text","text":"تراعى مهلة وصول الرسالة وفهمها وقدرة الجهات والمجتمعات على اتخاذ الإجراء المناسب."},{"type":"text","text":"تختبر الإجراءات عبر تمارين دورية وسيناريوهات متعددة وتوثق فجوات الاتصال والموارد."},{"type":"text","text":"بعد الحدث تجمع البيانات وتراجع القرارات والتوقعات والتأثيرات بصورة منهجية."},{"type":"text","text":"تحول نتائج المراجعة إلى إجراءات تصحيحية محددة المسؤول والموعد ومؤشر الإنجاز."},{"type":"text","text":"مثال تطبيقي: تمرين مكتبي يحاكي تطور حالة جوية شديدة من الرصد الأولي إلى التحذير ثم الاستجابة والتقييم."},{"type":"callout","text":"الخلاصة: إدارة الكوارث الجوية سلسلة مؤسسية متكاملة لا تنجح بالتحذير وحده دون استعداد واتصال واستجابة وتعلم."}]}',4950,55,'["تحديد الأدوار والمسؤوليات","تطبيق إجراءات الاستعداد والاستجابة","تقييم الأداء وتحسين المنظومة"]','الاستجابة والتعافي والتقييم'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'إدارة المخاطر والاستعداد' then u1.id else u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'إدارة الكوارث والاستجابة للطوارئ الجوية',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;